package com.salespunch360.mobile.ui.account.sales
import android.content.Intent;import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.LazyRow;import androidx.compose.foundation.lazy.items;import androidx.compose.foundation.lazy.itemsIndexed;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.Add;import androidx.compose.material.icons.filled.Refresh;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.platform.LocalContext;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.core.content.FileProvider;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import java.io.File;import kotlinx.serialization.json.*
@Composable fun QuotationScreen(padding:PaddingValues,vm:QuotationViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value,context=LocalContext.current;LaunchedEffect(s.pdf){s.pdf?.let{bytes->val file=File(context.cacheDir,"quotation.pdf");file.writeBytes(bytes);val uri=FileProvider.getUriForFile(context,"${context.packageName}.files",file);context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share quotation"));vm.consumedPdf()}};s.shareToken?.let{token->LaunchedEffect(token){context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"https://www.salespunch360.com/share/quotation/$token"),"Share quotation link"))}};Column(Modifier.fillMaxSize().padding(padding).padding(horizontal=16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search quotations")},modifier=Modifier.weight(1f));IconButton(vm::refresh){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton(vm::create){Icon(Icons.Default.Add,"New quotation")}};LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){item{FilterChip(s.status==null,{vm.filter(null)},{Text("All")})};items(listOf("DRAFT","PENDING_APPROVAL","APPROVED","SENT","ACCEPTED","REJECTED","DECLINED","EXPIRED","CANCELLED")){x->FilterChip(s.status==x,{vm.filter(x)},{Text(x.replace('_',' '))})}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(s.rows,key={it.id}){q->ListItem(headlineContent={Text(q.number,fontWeight=FontWeight.Bold)},supportingContent={Text("${q.customer} · ${q.type} · R${q.revision}")},trailingContent={Column{Text("₹${q.total}");Text(q.status)}},modifier=Modifier.clickable{vm.open(q.id)})}}};s.draft?.let{QuotationEditor(it,s,vm)};s.detail?.let{QuotationDetail(it,vm)}}
@Composable private fun QuotationEditor(d:QuotationDraft,s:QuotationState,vm:QuotationViewModel){AlertDialog(onDismissRequest=vm::closeDraft,title={Text(if(d.id==null)"New quotation" else if(d.revision)"New revision" else "Edit quotation")},confirmButton={Button(enabled=!s.saving&&d.customerId.isNotBlank()&&d.lines.isNotEmpty(),onClick=vm::save){Text("Save")}},dismissButton={TextButton(vm::closeDraft){Text("Cancel")}},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{SelectField("Type",d.documentType,listOf("QUOTATION" to "Quotation","ESTIMATE" to "Estimate","BOQ" to "BOQ")){vm.editDraft(d.copy(documentType=it))}};item{SelectField("Branch",d.branchId,s.branches.map{it.id to it.name}){vm.editDraft(d.copy(branchId=it,customerId=""))}};item{SelectField("Customer",d.customerId,s.customers.map{it.id to it.name}){vm.editDraft(d.copy(customerId=it))}};item{OutlinedTextField(d.issueDate,{vm.editDraft(d.copy(issueDate=it))},label={Text("Issue date")})};item{OutlinedTextField(d.validUntil,{vm.editDraft(d.copy(validUntil=it))},label={Text("Valid until")})};itemsIndexed(d.lines){i,l->QuotationLine(i,l,s,vm)};item{OutlinedButton(vm::addLine){Text("Add line")}};item{OutlinedTextField(d.terms,{vm.editDraft(d.copy(terms=it))},label={Text("Terms")},minLines=2)};item{OutlinedTextField(d.inclusions,{vm.editDraft(d.copy(inclusions=it))},label={Text("Inclusions")})};item{OutlinedTextField(d.exclusions,{vm.editDraft(d.copy(exclusions=it))},label={Text("Exclusions")})};item{OutlinedTextField(d.notes,{vm.editDraft(d.copy(notes=it))},label={Text("Notes")})};item{Text("All totals and lifecycle validation are calculated by the server.",style=MaterialTheme.typography.bodySmall)}}})}
@Composable private fun QuotationLine(i:Int,l:SalesLineDraft,s:QuotationState,vm:QuotationViewModel){val masters=when(l.lineType){"PRODUCT"->s.products;"SERVICE"->s.services;"WORK_PACKAGE"->s.workPackages;else->emptyList()};ElevatedCard{Column(Modifier.padding(10.dp)){SelectField("Line type",l.lineType,listOf("PRODUCT" to "Product","SERVICE" to "Service","WORK_PACKAGE" to "Work package","CUSTOM" to "Custom")){vm.line(i,l.copy(lineType=it,sourceId=""))};if(l.lineType=="CUSTOM")OutlinedTextField(l.itemName,{vm.line(i,l.copy(itemName=it))},label={Text("Name")})else SelectField("Item",l.sourceId,masters.map{it.id to it.name}){id->val m=masters.first{it.id==id};vm.line(i,l.copy(sourceId=id,rate=m.rate.orEmpty(),taxRate=m.taxRate.orEmpty()))};Row{OutlinedTextField(l.quantity,{vm.line(i,l.copy(quantity=it))},label={Text("Qty")},modifier=Modifier.weight(1f));OutlinedTextField(l.rate,{vm.line(i,l.copy(rate=it))},label={Text("Rate")},modifier=Modifier.weight(1f))};OutlinedTextField(l.taxRate,{vm.line(i,l.copy(taxRate=it))},label={Text("GST %")});if((s.draft?.lines?.size?:0)>1)TextButton({vm.removeLine(i)}){Text("Remove")}}}}
@Composable private fun QuotationDetail(q:kotlinx.serialization.json.JsonObject,vm:QuotationViewModel){val rev=q.array("revisions").firstOrNull(),allowed=q["allowedTransitions"]?.jsonArray?.map{it.jsonPrimitive.content}.orEmpty();AlertDialog(onDismissRequest=vm::close,title={Text(q.str("documentNumber"))},confirmButton={},dismissButton={TextButton(vm::close){Text("Close")}},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("${q.str("documentType")} · ${q.str("status")}",fontWeight=FontWeight.Bold);Text(rev?.str("customerName").orEmpty());Text("Grand total ₹${rev?.str("grandTotal").orEmpty()}")};rev?.array("lines")?.let{lines->items(lines){l->Text("${l.str("itemName")} · ${l.str("quantity")} × ₹${l.str("rate")} = ₹${l.str("lineTotal")}")}};item{allowed.forEach{to->Button({vm.transition(to)},Modifier.fillMaxWidth()){Text(to.replace('_',' '))}};if(q.str("status") in listOf("DRAFT","APPROVED","REJECTED","SENT","DECLINED","EXPIRED"))OutlinedButton(vm::revise,Modifier.fillMaxWidth()){Text(if(q.str("status")=="DRAFT")"Edit" else "Create revision")};if(q.str("status") in listOf("APPROVED","SENT"))OutlinedButton(vm::share,Modifier.fillMaxWidth()){Text("Share link")};OutlinedButton(vm::download,Modifier.fillMaxWidth()){Text("Download / share PDF")}}}})}
